import functools
import time


def throttle(seconds):
    def decorator(func):
        last = [0.0]

        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            now = time.monotonic()
            if now - last[0] >= seconds:
                last[0] = now
                return func(*args, **kwargs)
        return wrapper
    return decorator
