def max_subarray_sum(arr, k):
    window = sum(arr[:k])
    best, best_start = window, 0
    for i in range(k, len(arr)):
        window += arr[i] - arr[i - k]
        if window > best:
            best, best_start = window, i - k + 1
    return best, best_start
