def delete_node(root, val):
    if not root:
        return None
    if val < root.val:
        root.left = delete_node(root.left, val)
    elif val > root.val:
        root.right = delete_node(root.right, val)
    else:
        if not root.left:
            return root.right
        if not root.right:
            return root.left
        min_right = min_val_bst(root.right)
        root.val = min_right
        root.right = delete_node(root.right, min_right)
    return root

