def diff_dirs(dir_a, dir_b):
    a, b = Path(dir_a), Path(dir_b)
    differing = []
    for fa in a.rglob("*"):
        if fa.is_file():
            rel = fa.relative_to(a)
            fb = b / rel
            if not fb.exists() or file_hash(fa) != file_hash(fb):
