class RandomNode:
    def __init__(self, val):
        self.val = val
        self.next = None
        self.random = None

def copy_random_list(head):
    if not head:
        return None
    mapping = {}
    current = head
    while current:
        mapping[current] = RandomNode(current.val)
        current = current.next
    current = head
    while current:
        if current.next:
            mapping[current].next = mapping[current.next]
        if current.random:
            mapping[current].random = mapping[current.random]
        current = current.next
    return mapping[head]

